import{SKILLS}from'./expedition-data.mjs';
import{COURIER_ROOMS}from'./expedition-courier.mjs';
export const FIELDMEDIC_MOTION_RULE='仅表现当前步已记录的收信医师：施放、实际治疗与普通射击分别取自原事件；阈值未到、禁疗、缺蓝、缺药或有效恢复0时不画成功救护符号。900毫秒只是演出节奏，暂停或减少动态回到本步结算姿态，不改变HP、MP、库存或战报。';
export function fieldmedicMotion(group,config){
 if(config?.expedition!=='courier'||!group?.events?.length)return null;
 const template=COURIER_ROOMS[2].enemies.find(u=>u.id==='cfh'),unit=group.events.at(-1).units.find(u=>u.id===template.id&&u.side==='enemy');
 if(!unit||template.skills.heal===undefined)return null;
 const beats=[],seen=new Set(),add=(e,pose,label,ids=[e.id])=>beats.push({eventId:e.id,eventIds:ids,pose,label});
 for(const e of group.events){const d=e.detail||{},own=e.actor===unit.id,recipient=e.targets.includes(unit.id);
  if(own&&e.type==='cast'){if(d.skill==='heal')add(e,'prepare','施放草药救护 · MP '+d.mpBefore+'→'+d.mpAfter);else add(e,'assess',(d.healingDecision?'本步未自动治疗 · ':'')+(SKILLS[d.skill]?.name||'普通行动'));}
  if(own&&['failed','wait','item'].includes(e.type)&&d.healingDecision)add(e,'assess','本步未执行草药救护');
  if(own&&e.type==='heal'&&!d.passive&&!seen.has(d.cast??e.id)){seen.add(d.cast??e.id);const rows=group.events.filter(x=>x.actor===unit.id&&x.type==='heal'&&!x.detail.passive&&(d.cast===undefined?x.id===e.id:x.detail.cast===d.cast)),actual=rows.reduce((n,x)=>n+x.detail.actual,0);add(e,actual>0?'aid':'assess','有效治疗 '+actual+' · '+rows.length+'条记录',rows.map(x=>x.id));}
  if(own&&e.type==='attack')add(e,'assess',d.grade==='闪避'?'普通射击 · 实际闪避':'普通射击 · 生命实扣'+d.actual);
  if(recipient&&['attack','harm'].includes(e.type))add(e,d.grade==='闪避'?'evade':d.actual>0?'hit':'steady',d.grade==='闪避'?'实际闪避':'受击实扣 '+d.actual);
  if(recipient&&e.type==='down')add(e,'fallen','倒下');
 }
 return{id:unit.id,name:unit.name,settled:unit.hp<=0?'fallen':'idle',mode:beats.at(-1)?.pose||(unit.hp<=0?'fallen':'idle'),beats,sourceEvents:[...new Set(beats.flatMap(b=>b.eventIds))],label:beats.map(b=>b.label).join(' → ')||(unit.hp<=0?'已倒下':'待命'),rule:FIELDMEDIC_MOTION_RULE};
}
const idle={root:[0,0,0],torso:[0,0,0],head:[0,0,0],supplyArm:[0,0,0],supplyHand:[0,0,0],careArm:[0,0,0],careHand:[0,0,0],legL:[0,0,0],legR:[0,0,0],careMark:[0,0,0,0]},pose=x=>({...idle,...x});
export const FIELDMEDIC_POSES={idle,prepare:pose({torso:[0,0,-7],head:[0,0,-5],supplyArm:[0,0,-17],supplyHand:[0,0,-12],careArm:[0,0,-26],careHand:[0,0,-20]}),aid:pose({torso:[0,0,8],head:[0,0,3],supplyArm:[0,0,6],supplyHand:[0,0,14],careArm:[0,0,24],careHand:[0,0,20],careMark:[1,-2,42,1]}),assess:pose({torso:[0,0,2],head:[0,0,7],supplyArm:[0,0,3],careArm:[0,0,7],careHand:[0,0,9],careMark:[0,0,0,0]}),hit:pose({root:[-2,0,-5],torso:[0,0,-13],head:[0,0,-10],supplyArm:[0,0,11],careArm:[0,0,16]}),steady:pose({torso:[0,0,-3],supplyArm:[0,0,4]}),evade:pose({root:[-4,0,-9],torso:[0,0,-8],head:[0,0,5],supplyArm:[0,0,8],careArm:[0,0,-7]}),fallen:pose({root:[38,-42,-74],torso:[0,0,-7],head:[0,0,-10],supplyArm:[0,0,9],careArm:[0,0,18],legL:[0,0,-8],legR:[0,0,10]})};
const transform=([x,y,a])=>`translate(${x}px, ${y}px) rotate(${a}deg)`,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function fieldmedicKeyframes(plan,{speed=1,reduced=false}={}){
 if(![.5,1,2,4].includes(speed))throw Error('动作播放速度无效');
 const settled=FIELDMEDIC_POSES[plan.settled],poses=[{offset:0,pose:plan.settled==='fallen'&&!plan.beats.length?settled:idle},...plan.beats.map((b,i)=>({offset:(i+1)/(plan.beats.length+2),pose:FIELDMEDIC_POSES[b.pose]})),{offset:1,pose:settled}];
 return{duration:900/speed,animated:!reduced&&plan.beats.length>0,parts:Object.fromEntries(Object.keys(idle).map(key=>[key,{settled:transform(settled[key]),opacity:settled[key][3]??1,frames:poses.map(p=>({offset:p.offset,transform:transform(p.pose[key]),opacity:p.pose[key][3]??1}))}]))};
}
export function fieldmedicFigure(plan){return`<svg class="fieldmedic-figure" viewBox="-24 -20 168 164" aria-hidden="true" focusable="false" data-fieldmedic-id="${esc(plan.id)}" data-fieldmedic-motion="${esc(plan.mode)}" data-motion-events="${esc(plan.sourceEvents.join(','))}"><ellipse class="fieldmedic-shadow" cx="60" cy="${plan.settled==='fallen'?115:119}" rx="30" ry="${plan.settled==='fallen'?3:5}"/><g data-fieldmedic-part="root"><path class="fieldmedic-cloak" d="M42 40Q29 70 31 108L86 105Q82 66 75 40Z"/><g data-fieldmedic-part="legL"><path class="fieldmedic-leg" d="M48 78L47 101L44 116H57L61 80Z"/><path class="fieldmedic-boot" d="M44 110H58L59 119H40Z"/></g><g data-fieldmedic-part="legR"><path class="fieldmedic-leg" d="M63 78L67 101L69 116H81L76 80Z"/><path class="fieldmedic-boot" d="M68 111H81L85 119H67Z"/></g><g data-fieldmedic-part="torso"><path class="fieldmedic-robe" d="M42 44Q60 36 76 43L78 85L45 87Z"/><path class="fieldmedic-trim" d="M47 42L59 54L71 41L68 77H52Z"/><path class="fieldmedic-ink" d="M53 57h12m-12 6h12m-12 6h12"/><path class="fieldmedic-belt" d="M44 75L77 73L78 81L45 86Z"/><g data-fieldmedic-part="head"><path class="fieldmedic-hood" d="M43 32Q41 8 60 10Q80 10 78 35L69 44L50 41Z"/><path class="fieldmedic-mask" d="M50 25Q61 17 72 26L69 36L61 42L52 35Z"/><path class="fieldmedic-eye" d="M52 29h5m7 0h6"/><path class="fieldmedic-trim" d="M48 38L60 45L72 37L69 48H51Z"/></g><g data-fieldmedic-part="supplyArm"><path class="fieldmedic-robe" d="M44 44L35 49L41 69L53 66Z"/><g data-fieldmedic-part="supplyHand"><path class="fieldmedic-glove" d="M43 62L52 62L59 72L54 80L46 75Z"/><path class="fieldmedic-trim" d="M41 62L51 59L56 67L45 72Z"/><path class="fieldmedic-satchel" d="M46 66H62V85H46Z"/><path class="fieldmedic-stitch" d="M48 70H60m-6 3v9m-4-5h8"/></g></g><g data-fieldmedic-part="careArm"><path class="fieldmedic-robe" d="M71 44L81 48L85 63L76 67L69 54Z"/><g data-fieldmedic-part="careHand"><path class="fieldmedic-glove" d="M78 61L86 64L88 79L81 82L77 72Z"/><path class="fieldmedic-trim" d="M78 74L88 72L91 81L79 85Z"/><path class="fieldmedic-glove" d="m80 82 8-3 9-3 2 4-10 7-8 1Z"/><g data-fieldmedic-part="careMark"><path class="fieldmedic-careMark" d="M93 54h8v9h9v8h-9v9h-8v-9h-9v-8h9Z"/></g></g></g></g></g></svg><span class="fieldmedic-pose-label">${esc(plan.beats.at(-1)?.label||(plan.settled==='fallen'?'已倒下':'待命'))}</span>`;}
export function animateFieldmedicFigures(root,plans,{speed=1,reduced=false}={}){const running=[];for(const plan of plans){const svg=[...root.querySelectorAll('[data-fieldmedic-id]')].find(n=>n.dataset.fieldmedicId===plan.id);if(!svg)continue;const k=fieldmedicKeyframes(plan,{speed,reduced});svg.dataset.motionDuration=String(k.duration);svg.dataset.motionAnimated=String(k.animated);for(const[key,p]of Object.entries(k.parts)){const n=svg.querySelector('[data-fieldmedic-part="'+key+'"]');n.style.transform=p.settled;n.style.opacity=p.opacity;if(k.animated&&typeof n.animate==='function')running.push(n.animate(p.frames,{duration:k.duration,easing:'linear',fill:'none'}));}}return{cancel(){for(const a of running)a.cancel();},count:running.length};}
